#!/bin/bash

# 1. 缩短无意义的长时间等待，改成 10 秒缓冲网络即可
sleep 10

# 2. 安装 DD 脚本必须的前置依赖
export DEBIAN_FRONTEND=noninteractive
apt-get update -y
apt-get install -y xz-utils openssl gawk file wget curl net-tools iproute2

# 3. 终极防杀版 DD 命令（修改了 Base64 里面的代码，加入 nohup 防闪退机制）
bash <(wget --no-check-certificate -qO- https://raw.githubusercontent.com/MoeClub/Note/master/InstallNET.sh) -d 12 -v 64 -a --firmware -p "NP1215GP55*3*AACAAC" -port 22 -cmd ""
